True from collections import Counter

def transform(grid):
    """Move the non-background pattern down by one row, preserving canvas size."""
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg for _ in range(w)] for _ in range(h)]
    for r in range(h - 1):
        for c, value in enumerate(grid[r]):
            if value != bg:
                out[r + 1][c] = value
    return out
